const fs=require('fs');
global.window={};
eval(fs.readFileSync('持仓面板/config.js','utf8').replace('window.PANEL_CONFIG','global.PANEL_CONFIG'));
const cfg=global.PANEL_CONFIG;
function mkEl(){return {innerHTML:'',textContent:'',checked:false,onchange:null,style:{},_bound:false};}
const els={candBody:mkEl(),candNote:mkEl(),candHead:mkEl(),candOnlyHit:mkEl()};
function $(sel){const id=String(sel).replace('#','');return els[id]||null;}
global.document={getElementById:(id)=>els[id]||null};
const CFG=cfg;
function esc(s){return String(s==null?'':s);}
function fmt(v,d){return (v==null||!isFinite(v))?'—':Number(v).toFixed(d==null?2:d);}
const html=fs.readFileSync('持仓面板/index.html','utf8');
const start=html.indexOf('function renderCandidates()');
let i=html.indexOf('{',start),depth=0,end=-1;
for(;i<html.length;i++){if(html[i]==='{')depth++;else if(html[i]==='}'){depth--;if(depth===0){end=i+1;break;}}}
eval(html.slice(start,end));
renderCandidates();
const rows=(els.candBody.innerHTML.match(/<tr>/g)||[]).length;
console.log('rows:',rows);
const r0=els.candBody.innerHTML.split('</tr>')[0];
console.log('td per row:',(r0.match(/<td/g)||[]).length,'(expect 17)');
console.log('has ⚠️ warn:', els.candBody.innerHTML.includes('⚠️'));
// header th count
const thead=(html.match(/id="candTable"[\s\S]*?<\/thead>/)||[''])[0];
console.log('thead th count:',(thead.match(/<th/g)||[]).length,'(expect 17)');
els.candOnlyHit.checked=true; renderCandidates();
console.log('onlyHit rows:',(els.candBody.innerHTML.match(/<tr>/g)||[]).length);
console.log('OK');
